```tsx
import "./AlertBanner.css";

export interface AlertBannerProps {
  message: string;
  onRetry: () => void;
}

export function AlertBanner({ message, onRetry }: AlertBannerProps) {
  return (
    <div className="alert-banner" role="alert">
      <p className="alert-banner__message">{message}</p>
      <button type="button" className="alert-banner__retry" onClick={onRetry}>
        Retry
      </button>
    </div>
  );
}
```

```css
.alert-banner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75em 1.25em;
  padding: 0.85em 1.1em;
  border: 1px solid var(--cresyl);
  border-radius: 12px;
  background: var(--cresyl-wash);
  color: var(--ink);
  font-size: clamp(0.875rem, 0.8rem + 0.3vw, 1rem);
}

.alert-banner__message {
  margin: 0;
  flex: 1 1 16em;
  min-width: 0;
  color: var(--ink);
  overflow-wrap: anywhere;
}

.alert-banner__retry {
  font: inherit;
  font-weight: 600;
  padding: 0.4em 1.1em;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: var(--slide);
  color: var(--ink);
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease;
}

.alert-banner__retry:hover {
  background: var(--myelin-wash);
  border-color: var(--myelin);
}

.alert-banner__retry:focus-visible {
  border-color: var(--cresyl);
}

:root[data-motion="reduce"] .alert-banner__retry {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .alert-banner__retry {
    transition: none;
  }
}
```

